// "What we covered" (docs/06-coverage.qmd): built in the browser from the section's marks and the book's latest
// build record. Three views, a date range, print, copy as Markdown. Public sections need no sign-in.
import * as api from '../../frame/src/api.ts'
import type { MarkRow, TocPage, PackageRow } from '../../shared/types.ts'
import { renderMd } from '../../frame/src/ui/Md.tsx'

const $ = (id: string) => document.getElementById(id)!
const out = $('out')
const params = new URLSearchParams(location.search)
const slug = params.get('section')

type View = 'meeting' | 'chapter' | 'not'
let view: View = (params.get('view') as View) || 'meeting'
let from = params.get('from') || ''
let to = params.get('to') || ''

interface Data { pkg: PackageRow; pages: TocPage[]; marks: MarkRow[]; meetings: api.Meeting[]; sectionId: string; label: string }
let data: Data[] = []
let sectionTitle = ''

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!)
const fmt = (d: string) => new Date(d + 'T12:00:00').toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })
const STATUS: Record<string, string> = { covered: 'Covered', assigned: 'Read on your own', skipped: 'Skipped', comment: 'Comment' }

function markDate(m: MarkRow): string {
  return m.sections[0]?.meets_on || m.created_at.slice(0, 10)
}
function inRange(m: MarkRow): boolean {
  const d = markDate(m)
  return (!from || d >= from) && (!to || d <= to)
}
function pageOf(d: Data, m: MarkRow): TocPage | undefined {
  return d.pages.find((p) => p.page === m.page)
}
function link(d: Data, m: MarkRow): string {
  const p = pageOf(d, m)
  return p ? `${d.pkg.site_url}${p.path}#yrS4=${m.id}` : '#'
}
function what(m: MarkRow): string {
  const a = m.anchor_current || m.anchor
  if (!a) return 'the whole book'
  if (a.scope === 'page') return 'the whole page'
  if (a.scope === 'section') return `§ ${a.section?.headings.slice(-1)[0] || ''}`
  return a.quote ? `“${a.quote.exact.length > 160 ? a.quote.exact.slice(0, 160) + '…' : a.quote.exact}”` : ''
}
function where(d: Data, m: MarkRow): string {
  const p = pageOf(d, m)
  const a = m.anchor_current || m.anchor
  const sec = a?.section?.headings?.length && a.scope !== 'section' ? ' › ' + a.section.headings.join(' › ') : ''
  return (p?.title || m.page || '') + sec
}
function status(m: MarkRow): string {
  return m.kind === 'comment' ? 'comment' : (m.data.status as string) || 'covered'
}
function item(d: Data, m: MarkRow, showDate: boolean): string {
  const st = status(m)
  const date = showDate ? `<span class="muted"> · ${fmt(markDate(m))}</span>` : ''
  const body = m.kind === 'comment' && m.body ? `<span class="cm">${renderMd(m.body)}</span>` : ''
  return `<li><span class="st st-${st}">${STATUS[st]}</span><a href="${esc(link(d, m))}">${esc(what(m))}</a> <span class="where">${esc(where(d, m))}</span>${date}${body}</li>`
}

function byMeeting(): string {
  const parts: string[] = []
  for (const d of data) {
    const marks = d.marks.filter(inRange)
    const groups = new Map<string, MarkRow[]>()
    for (const m of marks) groups.set(markDate(m), [...(groups.get(markDate(m)) || []), m])
    const dates = [...groups.keys()].sort().reverse()
    if (data.length > 1) parts.push(`<h2>${esc(d.pkg.title)}</h2>`)
    if (!dates.length) parts.push('<p class="muted">Nothing marked yet.</p>')
    for (const date of dates) {
      const mt = d.meetings.find((x) => x.meets_on === date)
      parts.push(`<h2>${fmt(date)}${mt?.title ? ` · ${esc(mt.title)}` : ''}</h2>`)
      if (mt?.note) parts.push(`<div class="note">${renderMd(mt.note)}</div>`)
      const ms = groups.get(date)!.sort((a, b) => d.pages.findIndex((p) => p.page === a.page) - d.pages.findIndex((p) => p.page === b.page) || (a.anchor?.position?.start || 0) - (b.anchor?.position?.start || 0))
      parts.push('<ul>' + ms.map((m) => item(d, m, false)).join('') + '</ul>')
    }
  }
  return parts.join('\n')
}

function byChapter(not = false): string {
  const parts: string[] = []
  for (const d of data) {
    if (data.length > 1) parts.push(`<h2>${esc(d.pkg.title)}</h2>`)
    const marks = d.marks.filter(inRange)
    let part: string | undefined
    for (const p of d.pages) {
      const ms = marks.filter((m) => m.page === p.page)
      if (not ? ms.length : !ms.length) continue
      if (p.part !== part) {
        part = p.part
        if (part) parts.push(`<h2>${esc(part)}</h2>`)
      }
      parts.push(`<h3><a href="${esc(d.pkg.site_url + p.path)}">${esc(p.title)}</a></h3>`)
      if (!not) parts.push('<ul>' + ms.sort((a, b) => (a.anchor?.position?.start || 0) - (b.anchor?.position?.start || 0)).map((m) => item(d, m, true)).join('') + '</ul>')
    }
    if (!parts.length) parts.push(`<p class="muted">${not ? 'Everything has coverage.' : 'Nothing marked yet.'}</p>`)
  }
  return parts.join('\n')
}

function asMarkdown(): string {
  const lines: string[] = [`# What we covered: ${sectionTitle}`, '']
  for (const d of data) {
    const marks = d.marks.filter(inRange)
    const groups = new Map<string, MarkRow[]>()
    for (const m of marks) groups.set(markDate(m), [...(groups.get(markDate(m)) || []), m])
    for (const date of [...groups.keys()].sort().reverse()) {
      const mt = d.meetings.find((x) => x.meets_on === date)
      lines.push(`## ${fmt(date)}${mt?.title ? ` · ${mt.title}` : ''}`, '')
      if (mt?.note) lines.push(mt.note, '')
      for (const m of groups.get(date)!) lines.push(`- **${STATUS[status(m)]}** [${what(m).replace(/\n/g, ' ')}](${link(d, m)}) · ${where(d, m)}${m.kind === 'comment' && m.body ? `\n  > ${m.body.replace(/\n/g, '\n  > ')}` : ''}`)
      lines.push('')
    }
  }
  return lines.join('\n')
}

function render() {
  for (const v of ['meeting', 'chapter', 'not'] as View[]) $('v-' + v).classList.toggle('on', view === v)
  out.innerHTML = view === 'meeting' ? byMeeting() : byChapter(view === 'not')
  const u = new URL(location.href)
  u.searchParams.set('view', view)
  from ? u.searchParams.set('from', from) : u.searchParams.delete('from')
  to ? u.searchParams.set('to', to) : u.searchParams.delete('to')
  history.replaceState(null, '', u)
}

async function main() {
  if (!slug) {
    out.innerHTML = '<p>Add <code>?section=…</code> to this address (the section slug from your instructor\'s link).</p>'
    return
  }
  const section = await api.sectionBySlug(slug)
  if (!section) {
    out.innerHTML = `<p>No section called <code>${esc(slug)}</code> is visible to you. If it's private, sign in through the book's panel first.</p>`
    return
  }
  sectionTitle = `${section.course?.title || section.course?.code || ''} · section ${section.label} · ${section.term}`
  $('title').textContent = 'What we covered'
  $('subtitle').textContent = sectionTitle
  document.title = `What we covered · ${section.label}`
  const pkgs = await Promise.all(section.packages.map(async (id) => {
    const { data: rows } = await api.sb().from('packages').select('*').eq('id', id)
    return rows?.[0] as PackageRow | undefined
  }))
  data = []
  for (const pkg of pkgs) {
    if (!pkg) continue
    const [build, marks, meetings] = await Promise.all([api.latestBuild(pkg.id, true), api.pageMarks(pkg.id, null, ['coverage', 'comment']), api.meetingsFor([section.id])])
    data.push({ pkg, pages: build?.toc?.pages || [], marks: marks.filter((m) => m.sections.some((s) => s.section_id === section.id)), meetings, sectionId: section.id, label: section.label })
  }
  ;($('from') as HTMLInputElement).value = from
  ;($('to') as HTMLInputElement).value = to
  render()
}

for (const v of ['meeting', 'chapter', 'not'] as View[]) $('v-' + v).addEventListener('click', () => { view = v; render() })
$('from').addEventListener('change', (e) => { from = (e.target as HTMLInputElement).value; render() })
$('to').addEventListener('change', (e) => { to = (e.target as HTMLInputElement).value; render() })
$('print').addEventListener('click', () => window.print())
$('copy').addEventListener('click', async () => {
  await navigator.clipboard.writeText(asMarkdown())
  ;($('copy') as HTMLButtonElement).textContent = 'Copied'
  setTimeout(() => (($('copy') as HTMLButtonElement).textContent = 'Copy as Markdown'), 1500)
})
main().catch((e) => { out.innerHTML = `<p class="muted">Couldn't load: ${esc(String(e))}</p>` })
